import{z as B,x as o,o as e,c as p,q as t,j as l,D as E,d as s,s as n,S as i,b as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"MAC 学习与洪泛","description":"","frontmatter":{"title":"MAC 学习与洪泛","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mac-learning.md","filePath":"cs/mac-learning.md","lastUpdated":1791063341000}'),d={name:"cs/mac-learning.md"};function C(m,a,c,h,u,D){const r=o("Mermaid");return e(),p("div",null,[a[2]||(a[2]=t('<h1 id="mac-学习与洪泛" tabindex="-1">MAC 学习与洪泛 <a class="header-anchor" href="#mac-学习与洪泛" aria-label="Permalink to &quot;MAC 学习与洪泛&quot;">​</a></h1><div class="epigraph"><p>源地址写入入端口的转发表，目的命中则单播，未知、广播、组播则洪泛；表会老化，环会让表振荡。</p><footer>—— 据 Kurose and Ross 交换章；IEEE 802.1Q 转发表条款整理</footer></div><p><a href="/cs/rstp-mstp">上一课</a>保证无环之后，洪泛才安全。主干<a href="/cs/csma-switch">CSMA 与交换</a> 已给过学习直觉。缺口是<strong>表项生命周期与洪泛集合</strong>：老化、VLAN 隔离、未知单播行为、与 LACP 逻辑口。本课不把交换芯片背板写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>帧进来：学源 MAC → 查目的。命中且出口≠入口则转发；同口则过滤（到自己）。未命中：向该 VLAN 内除入口外的转发态口洪泛。老化（常见 300 s）防止主机搬家后黑洞。RSTP 拓扑变更缩短老化，否则帧仍从旧口出。</p><p>组播若无 IGMP 窥探（后课）当广播洪泛。这是二层默认，不是 bug。</p><p><span class="marginnote">表容量有限：溢出则更多未知洪泛，像回到集线器。CAM 耗尽攻击是安全课对象，本课只钉机制。</span></p><p><span class="marginnote">直觉类比：交换机像门卫记人脸——谁来过就记下「这张脸走哪个门」。收件人没登记过（未知单播）就把信挨个门喊一遍（洪泛），谁应答就记下谁。喊一圈是学习的代价，不是网络故障；喊过之后同一收件人就走单播了。</span></p><h3 id="学源查宿" tabindex="-1">学源查宿 <a class="header-anchor" href="#学源查宿" aria-label="Permalink to &quot;学源查宿&quot;">​</a></h3><p>未知单播在 VLAN 内洪泛；表满则更像集线器。TCN 缩短老化，否则走旧口。ARP 表在主机，交换机只搬 MAC。</p><p><span class="marginnote">数字实例：老化时间常见 300 秒。若笔记本从口 1 挪到口 3 后保持沉默，旧表项最长还能「活」5 分钟，期间发往它的帧全从口 1 出、被丢——这正是拓扑变更要把老化缩到秒级的理由。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：学习、查找、洪泛、老化、TCN 冲刷。对照路由器：路由器不因源 IP 学出接口来转发（除某些特殊），交换机必须学。LACP：学在逻辑口上，哈希再选成员。</p>',13)),(e(),l(i,null,{default:E(()=>[n(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%85%A5%E5%B8%A7%22%5D%20--%3E%20LRN%5B%22%E5%AD%A6%E6%BA%90%20MAC%22%5D%0A%20%20LRN%20--%3E%20LK%5B%22%E6%9F%A5%E7%9B%AE%E7%9A%84%22%5D%0A%20%20LK%20--%3E%20HIT%5B%22%E5%8D%95%E7%AB%AF%E5%8F%A3%E5%87%BA%22%5D%0A%20%20LK%20--%3E%20FLOOD%5B%22VLAN%20%E5%86%85%E6%B4%AA%E6%B3%9B%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[s("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,"巨帧、PAUSE 不改学习键：键是 MAC+VLAN。LLDP 源 MAC 也会被学到，除非控制帧另通道。生成树阻塞口不学习数据，仍可收 BPDU。",-1)),a[5]||(a[5]=A("p",null,"未知单播洪泛会把流量送到所有接入口：大二层数据中心的痛点，后课 VXLAN/EVPN 用控制面分发 MAC 来收敛洪泛。",-1)),(e(),l(i,null,{default:E(()=>[n(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20T0%5B%22%E8%A1%A8%E9%A1%B9%20A%20%E6%8C%87%E5%90%91%E5%8F%A3%201%22%5D%20--%3E%20MOVE%5B%22%E4%B8%BB%E6%9C%BA%20A%20%E6%90%AC%E5%88%B0%E5%8F%A3%203%20%E4%B8%94%E6%9A%82%E4%B8%8D%E5%8F%91%E5%B8%A7%22%5D%0A%20%20MOVE%20--%3E%20STALE%5B%22%E6%97%A7%E8%A1%A8%E9%A1%B9%E6%9C%AA%E5%88%B0%E6%9C%9F%2C%20%E5%8F%91%E5%BE%80%20A%20%E7%9A%84%E5%B8%A7%E4%BB%8D%E4%BB%8E%E5%8F%A3%201%20%E5%87%BA%22%5D%0A%20%20STALE%20--%3E%20BLACK%5B%22%E5%8F%A3%201%20%E5%90%8E%E9%9D%A2%E6%B2%A1%E6%9C%89%20A%3A%20%E4%B8%A2%E5%8C%85%E9%BB%91%E6%B4%9E%22%5D%0A%20%20MOVE%20--%3E%20TIMER%5B%22%E8%80%81%E5%8C%96%E8%AE%A1%E6%97%B6%E5%99%A8%E5%80%92%E6%95%B0%20(%E5%B8%B8%E8%A7%81%20300%20s)%22%5D%0A%20%20TIMER%20--%3E%20TCN%5B%22%E7%94%9F%E6%88%90%E6%A0%91%E6%8B%93%E6%89%91%E5%8F%98%E6%9B%B4%3A%20%E8%80%81%E5%8C%96%E7%BC%A9%E5%88%B0%E8%BD%AC%E5%8F%91%E6%97%B6%E5%BB%B6%E7%BA%A7%22%5D%0A%20%20TCN%20--%3E%20FLUSH%5B%22%E6%97%A7%E8%A1%A8%E9%A1%B9%E5%86%B2%E5%88%B7%2C%20A%20%E7%9A%84%E4%B8%8B%E4%B8%80%E5%B8%A7%E4%BB%8E%E5%8F%A3%203%20%E9%87%8D%E6%96%B0%E5%AD%A6%E4%B9%A0%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">常见误区：初学者容易把洪泛等同于广播风暴。未知单播/广播洪泛每帧只喊一次，学习收敛后转单播；风暴来自物理环路让帧无限自我复制。所以次序是：生成树先拆环，洪泛才安全——环拆晚了，表还会随复制帧来回振荡。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 EVPN 路由类型。交换机架构与背板是下一课。后课默认：学习+老化+洪泛是二层转发的全部控制面（无路由协议）。</p><p>不要把 MAC 表当成 ARP 表：ARP 在主机把 IP 映到 MAC；交换机只搬 MAC。</p><p>下一课<a href="/cs/switch-fabric">交换机架构与背板</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>学源、查宿；未知则 VLAN 洪泛。</li><li>老化与 TCN 防止走旧口。</li><li>表满则洪泛增多。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Kurose and Ross；IEEE 802.1Q。</li></ul>',7))])}const P=B(d,[["render",C]]);export{f as __pageData,P as default};
